import {SERVICES,BARBERS,STORAGE_KEY,todayKey,addDays,dateLabel,serviceById,barberById,seedBookings,availableBarber,dailyStats,timeNumber,timeString} from './model.js';

const TODAY=todayKey();
const app=document.querySelector('#app');
const dialog=document.querySelector('#success-dialog');
const state={view:'customer',step:0,service:'hair',barber:'any',date:TODAY,time:null,adminDate:TODAY,walkinOpen:false,details:{name:'',phone:'',note:''},bookings:loadBookings()};
const escapeHTML=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let toastTimer;
function toast(message){const el=document.querySelector('#toast');el.textContent=message;el.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('visible'),4000);}
function loadBookings(){try{const saved=JSON.parse(sessionStorage.getItem(STORAGE_KEY));if(saved?.day===TODAY && Array.isArray(saved.bookings) && saved.bookings.every(b=>b && typeof b.id==='string' && /^\d{4}-\d{2}-\d{2}$/.test(b.date) && /^\d{2}:\d{2}$/.test(b.time) && serviceById(b.service) && ['viktor','marko'].includes(b.barber) && ['confirmed','completed','cancelled'].includes(b.status)))return saved.bookings;}catch{}return seedBookings(TODAY);}
function persist(){try{sessionStorage.setItem(STORAGE_KEY,JSON.stringify({day:TODAY,bookings:state.bookings}));}catch{toast('Демото работи без зачувување по освежување.');}}
function switchView(view){state.view=view;render();window.scrollTo({top:0,behavior:'smooth'});}
document.querySelector('#customer-tab').addEventListener('click',()=>switchView('customer'));
document.querySelector('#admin-tab').addEventListener('click',()=>switchView('admin'));
document.querySelector('.brand').addEventListener('click',event=>{event.preventDefault();switchView('customer');});
document.querySelector('#reset-demo').addEventListener('click',()=>{if(!confirm('Да се избришат пробните резервации и да се врати почетното демо?'))return;state.bookings=seedBookings(TODAY);state.step=0;state.time=null;state.date=TODAY;state.adminDate=TODAY;state.details={name:'',phone:'',note:''};state.walkinOpen=false;persist();render();toast('Демото е ресетирано.');});

function render(){
  for(const view of ['customer','admin']){const tab=document.querySelector(`#${view}-tab`);tab.classList.toggle('active',state.view===view);tab.setAttribute('aria-pressed',String(state.view===view));}
  app.innerHTML=state.view==='customer'?customerView():adminView();
  bindEvents();
}
function customerView(){return `<div class="customer-layout"><aside class="editorial"><div class="eyebrow">HEADS UP BARBERSHOP</div><h1>Свеж изглед.<br><em>Без чекање.</em></h1><p class="intro">Закажи свој термин онлајн.<br>Избери услуга, бербер и време што ти одговара.</p><div class="location"><span>⌖</span> Струмица, Северна Македонија</div><div class="brand-art" aria-hidden="true"><div class="art-grid"></div><span class="art-number">41°26′ N / 22°38′ E</span><div class="art-seal"><small>THE BARBER CONCEPT</small><strong>HU↗</strong><span>LOOK SHARP. FEEL GOOD.</span></div><span class="art-corner">PRECISION / STYLE / CONFIDENCE</span></div><div class="editorial-note"><span>01 — Твојот следен добар изглед</span><span>STRUMICA, MK</span></div></aside><section class="booking" aria-label="Закажи термин"><nav class="steps" aria-label="Чекори">${['Услуга','Бербер','Термин','Потврда'].map((label,index)=>`<button class="step ${index===state.step?'active':index<state.step?'done':''}" data-step="${index}" ${index>state.step?'disabled':''} ${index===state.step?'aria-current="step"':''}><b>${index<state.step?'✓':index+1}</b>${label}</button>`).join('')}</nav>${[servicesView,barbersView,slotsView,detailsView][state.step]()}</section></div>`;}
const heading=(title,subtitle)=>`<div class="section-heading"><h2>${title}</h2><small>0${state.step+1} / 04</small></div><p class="helper">${subtitle}</p>`;
function summary(){const s=serviceById(state.service);return `<div class="summary-bar"><span>${s.name}<br><small>${s.duration} минути</small></span><strong>${s.price} <small>ДЕН</small></strong></div>`;}
function next(label,disabled=false){return `<button class="primary next-button" id="next" ${disabled?'disabled':''}><span>${label}</span><span aria-hidden="true">↗</span></button><p class="micro">Примерни цени и термини · Без вистинска резервација</p>`;}
function back(){return '<button class="back-button" id="back">← Назад</button>';}
function servicesView(){return heading('Избери ја твојата услуга','Добриот изглед почнува со вистинскиот избор.')+`<div class="service-list">${SERVICES.map(s=>`<button class="service-card ${state.service===s.id?'selected':''}" data-service="${s.id}" aria-pressed="${state.service===s.id}"><span class="service-icon" aria-hidden="true">${s.icon}</span><span class="service-info"><strong>${s.name}</strong><small>${s.duration} мин <span class="detail">· ${s.detail}</span></small></span><span class="price">${s.price}<small>ДЕНАРИ</small></span><span class="radio" aria-hidden="true"></span></button>`).join('')}</div>`+summary()+next('Продолжи кон бербер');}
function barbersView(){return heading('Избери бербер','Твојот омилен бербер, или првиот што е слободен.')+`<div class="barbers">${BARBERS.map(b=>`<button class="service-card ${state.barber===b.id?'selected':''}" data-barber="${b.id}" aria-pressed="${state.barber===b.id}"><span class="avatar" aria-hidden="true">${b.initial}</span><span class="service-info"><strong>${b.name}</strong><small>${b.id==='any'?'Повеќе слободни термини':'Бербер · Примерен профил'}</small></span><span class="radio" aria-hidden="true"></span></button>`).join('')}</div>`+summary()+next('Избери датум и време')+back();}
function slotsView(){const days=Array.from({length:7},(_,i)=>addDays(TODAY,i));const times=['10:00','10:40','11:20','12:00','12:40','13:20','14:00','14:40','15:00','15:40','16:20','17:00'];return heading('Кога ти одговара?','Избери слободен термин. Прикажаните часови се демо-пример.')+`<div class="chips"><button class="chip ${state.date===TODAY?'selected':''}" data-date="${TODAY}">Денес</button><button class="chip ${state.date===days[1]?'selected':''}" data-date="${days[1]}">Утре</button><span class="chip">${dateLabel(state.date,{month:'long',year:'numeric'})}</span></div><div class="dates">${days.map(day=>`<button class="date-card ${day===state.date?'selected':''}" data-date="${day}" aria-label="${dateLabel(day,{weekday:'long',day:'numeric',month:'long'})}" aria-pressed="${day===state.date}"><small>${dateLabel(day,{weekday:'short'})}</small><strong>${Number(day.slice(-2))}</strong></button>`).join('')}</div><div class="time-grid">${times.map(time=>{const free=availableBarber(state.bookings,state.date,time,state.barber,state.service);return `<button class="time-slot ${state.time===time?'selected':''}" data-time="${time}" ${free?'':'disabled'} aria-pressed="${state.time===time}" aria-label="${time}${free?' слободен':' зафатен'}">${time}</button>`;}).join('')}</div><div class="legend"><span><i></i>Слободен термин</span><span><i></i>Зафатен термин</span></div><p class="helper">${barberById(state.barber).name} · ${serviceById(state.service).duration} минути<br>Демо-распоред: 10:00–18:00, вклучително и изминати часови денес.</p>`+summary()+next('Продолжи кон потврда',!state.time)+back();}
function review(booking){const s=serviceById(booking.service),barber=barberById(booking.barber);return `<div class="review-card"><p><span>Услуга</span><strong>${s.name}</strong></p><p><span>Бербер</span><strong>${barber?.name??'Првиот слободен'}</strong></p><p><span>Датум и време</span><strong>${dateLabel(booking.date)} · ${booking.time}</strong></p><p><span>Вкупно · ${s.duration} мин</span><strong>${s.price} ДЕН</strong></p></div>`;}
function detailsView(){const resolved=availableBarber(state.bookings,state.date,state.time,state.barber,state.service);return heading('Уште еден чекор.','Внеси пробни податоци за да го испробаш закажувањето.')+review({...state,barber:resolved})+`<form id="booking-form"><label class="field">Име и презиме<input id="customer-name" name="name" autocomplete="off" placeholder="Пример: Александар Петров" required minlength="2" maxlength="80" value="${escapeHTML(state.details.name)}"></label><label class="field">Телефонски број<input id="customer-phone" name="phone" type="tel" inputmode="tel" autocomplete="off" placeholder="Пример: 070 000 000" required maxlength="25" value="${escapeHTML(state.details.phone)}"></label><label class="field">Забелешка <small>· незадолжително</small><textarea id="customer-note" name="note" maxlength="300" placeholder="Нешто што треба да знае берберот?">${escapeHTML(state.details.note)}</textarea></label><p id="form-error" class="error" role="alert"></p><button class="primary next-button" type="submit"><span>Потврди терминот</span><span>✓</span></button><p class="micro">Демо-резервацијата останува само во оваа сесија на прелистувачот.<br>Не внесувај вистински лични податоци. Не се испраќа СМС / Viber.</p></form>`+back();}
function adminView(){const stats=dailyStats(state.bookings,state.adminDate);const items=state.bookings.filter(b=>b.date===state.adminDate).sort((a,b)=>a.time.localeCompare(b.time));return `<section><div class="admin-header"><div><div class="eyebrow">HEADS UP / БЕРБЕРСКА КОНЗОЛА</div><h1>${state.adminDate===TODAY?'Денешен распоред':'Дневен распоред'}<span style="color:var(--accent)">.</span></h1><p class="helper">${dateLabel(state.adminDate,{weekday:'long',day:'numeric',month:'long',year:'numeric'})} · Примерни клиенти и приходи</p></div><div class="admin-controls"><input class="date-select" id="admin-date" type="date" value="${state.adminDate}" aria-label="Датум на распоред"><button class="primary" id="walkin-toggle" aria-expanded="${state.walkinOpen}">＋ Муштерија од место</button></div></div><div class="stats"><div class="stat"><small>Активни термини</small><strong>${String(stats.count).padStart(2,'0')}</strong></div><div class="stat"><small>Очекуван приход</small><strong>${stats.revenue.toLocaleString('mk-MK')} <span>ДЕН</span></strong></div><div class="stat"><small>Завршени термини</small><strong>${String(stats.completed).padStart(2,'0')} <span>/ ${stats.count}</span></strong></div></div>${state.walkinOpen?walkinView():''}<div class="schedule-title"><h2>Термини <span class="muted">(${items.length})</span></h2><span class="badge">ДЕМО · ЛОКАЛНА СЕСИЈА</span></div><div class="schedule">${items.length?items.map(appointmentView).join(''):'<div class="empty">Нема термини за овој ден.<br>Додај муштерија или пробај го закажувањето за клиенти.</div>'}</div><div class="admin-note"><strong style="color:var(--text)">Испробај го целиот процес.</strong> Закажи пробен термин во „За клиенти“ и ќе се појави тука веднаш, на избраниот датум. Откажувањето повторно го ослободува терминот. Ова е јавен демо-приказ, без најава и без вистински клиенти.</div></section>`;}
function appointmentView(b){const s=serviceById(b.service);const labels={confirmed:'Потврдено',completed:'Завршено',cancelled:'Откажано'};return `<article class="appointment ${b.status==='cancelled'?'cancelled-row':''}"><time>${b.time}<small>${s.duration} мин</small></time><p><strong>${escapeHTML(b.name)}</strong><small>${escapeHTML(b.phone||'Муштерија од место')}</small>${b.note?`<small>${escapeHTML(b.note)}</small>`:''}</p><p class="service-cell"><strong>${s.name}</strong><small>${s.price} ДЕН</small></p><p class="barber-cell"><strong>${barberById(b.barber).name}</strong><small>Бербер</small></p><p class="status-cell"><span class="status ${b.status}">${labels[b.status]}</span></p><div class="row-actions">${b.status==='confirmed'?`<button class="small-button" data-complete="${escapeHTML(b.id)}">✓ Завршено</button><button class="small-button" data-cancel="${escapeHTML(b.id)}">Откажи</button>`:'<span class="small-label">'+labels[b.status]+'</span>'}</div></article>`;}
function walkinView(){return `<form id="walkin-form" class="walkin-form"><label class="field">Бербер<select name="barber"><option value="viktor">Виктор</option><option value="marko">Марко</option></select></label><label class="field">Од колку часот?<input type="time" name="time" value="10:00" min="10:00" max="17:30" step="300" required></label><button class="primary" type="submit">Блокирај 30 мин</button><p class="walkin-info" style="grid-column:1/-1;margin:0">Машко шишање · 300 ДЕН · ${dateLabel(state.adminDate)}. Се проверува дали берберот е слободен.</p><p class="error" id="walkin-error" style="grid-column:1/-1;margin:0" role="alert"></p></form>`;}
function bindEvents(){
  app.querySelectorAll('[data-step]').forEach(el=>el.addEventListener('click',()=>{state.step=Number(el.dataset.step);render();}));
  app.querySelectorAll('[data-service]').forEach(el=>el.addEventListener('click',()=>{state.service=el.dataset.service;state.time=null;render();}));
  app.querySelectorAll('[data-barber]').forEach(el=>el.addEventListener('click',()=>{state.barber=el.dataset.barber;state.time=null;render();}));
  app.querySelectorAll('[data-date]').forEach(el=>el.addEventListener('click',()=>{state.date=el.dataset.date;state.time=null;render();}));
  app.querySelectorAll('[data-time]').forEach(el=>el.addEventListener('click',()=>{state.time=el.dataset.time;render();}));
  document.querySelector('#next')?.addEventListener('click',()=>{state.step++;render();focusHeading();});
  document.querySelector('#back')?.addEventListener('click',()=>{state.step--;render();focusHeading();});
  document.querySelector('#booking-form')?.addEventListener('submit',submitBooking);
  for(const key of ['name','phone','note'])document.querySelector(`#customer-${key}`)?.addEventListener('input',event=>{state.details[key]=event.target.value;});
  document.querySelector('#admin-date')?.addEventListener('change',event=>{if(event.target.value){state.adminDate=event.target.value;render();}});
  document.querySelector('#walkin-toggle')?.addEventListener('click',()=>{state.walkinOpen=!state.walkinOpen;render();});
  document.querySelector('#walkin-form')?.addEventListener('submit',submitWalkin);
  app.querySelectorAll('[data-complete]').forEach(el=>el.addEventListener('click',()=>updateStatus(el.dataset.complete,'completed')));
  app.querySelectorAll('[data-cancel]').forEach(el=>el.addEventListener('click',()=>{if(confirm('Да се откаже овој демо-термин?'))updateStatus(el.dataset.cancel,'cancelled');}));
}
function focusHeading(){const el=app.querySelector('.section-heading h2');if(el){el.tabIndex=-1;el.focus({preventScroll:true});el.scrollIntoView({block:'nearest',behavior:'smooth'});}}
function submitBooking(event){event.preventDefault();const error=document.querySelector('#form-error');const digits=state.details.phone.replace(/[\s()+-]/g,'');if(state.details.name.trim().length<2){error.textContent='Внеси име со најмалку 2 знаци.';return;}if(!/^(?:0[2-9]\d{7}|389[2-9]\d{7})$/.test(digits)){error.textContent='Внеси број во формат 070 000 000 или +389 70 000 000.';return;}const barber=availableBarber(state.bookings,state.date,state.time,state.barber,state.service);if(!barber){error.textContent='Терминот веќе е зафатен. Врати се и избери друг термин.';return;}const booking={id:crypto.randomUUID(),date:state.date,time:state.time,service:state.service,barber,status:'confirmed',name:state.details.name.trim(),phone:state.details.phone.trim(),note:state.details.note.trim()};state.bookings.push(booking);persist();state.adminDate=booking.date;showSuccess(booking);state.step=0;state.time=null;state.details={name:'',phone:'',note:''};render();}
function showSuccess(booking){dialog.innerHTML=`<div class="success-check">✓</div><h2 id="success-title">Твојот демо-термин е потврден!</h2><p class="helper">Сѐ е подготвено. Погледни го и во берберската конзола.</p>${review(booking)}<div class="message-preview"><strong>ПРЕГЛЕД НА СМС / VIBER ПОТВРДА</strong>„Успешно закажавте! Системот ви испраќа потврда преку СМС / Viber.“<br><span>Ова е пример за идната порака. Во демото не се испраќаат пораки и нема вистинска резервација.</span></div><button class="primary" id="go-admin">Префрли се на Берберска Конзола ↗</button><button class="text-button dialog-close" id="close-success">Назад кон закажување</button>`;dialog.showModal();document.querySelector('#go-admin').onclick=()=>{dialog.close();switchView('admin');};document.querySelector('#close-success').onclick=()=>dialog.close();}
function updateStatus(id,status){const item=state.bookings.find(b=>b.id===id);if(!item||item.status!=='confirmed')return;item.status=status;persist();render();toast(status==='completed'?'Терминот е означен како завршен.':'Терминот е откажан и повторно е слободен.');}
function submitWalkin(event){event.preventDefault();const data=new FormData(event.target);const barber=data.get('barber'),time=data.get('time');if(!availableBarber(state.bookings,state.adminDate,time,barber,'hair')){document.querySelector('#walkin-error').textContent='Берберот е зафатен или времето е надвор од 10:00–18:00. Избери друг термин.';return;}state.bookings.push({id:crypto.randomUUID(),date:state.adminDate,time,service:'hair',barber,status:'confirmed',name:'Муштерија од место',phone:'',note:'Блокирани 30 минути'});persist();state.walkinOpen=false;render();toast(`Додадено: ${time}–${timeString(timeNumber(time)+30)} кај ${barberById(barber).name}.`);}
render();
